Section HCW2.
  Context {HCEIL : HeapCeil} {HSEC : HeapSecret}.

Lemma RHEAP_init_proof : forall (m : mem) (auxv : word) (lc0 lc1 lc2 : byte) (lc4 t1 t2 t3 t4 : word) (loc : list byte),
  length loc = 48%nat ->
  (forall a : word, 0xb2950 <= bv_unsigned a < 0xb2cf8 -> m a = None) ->
  rw_cells rsegs m 0xb28e0 [C1 lc0; C1 lc1; C1 lc2; C1 (Z_to_bv 8 0); C4 lc4] ->
  rw_cells rsegs m 0xb28e8 [C8 auxv; C8 t1; C8 t2; C8 t3; C8 t4;
                            C8 (Z_to_bv 64 4096); CB 48 loc] ->
  rw_cells rsegs m 0x7f808 [C8 (Z_to_bv 64 0xb2690)] ->
  rw_cells rsegs m 0xb2690 [C8 (Z_to_bv 64 hcanary)] ->
  (forall a : word, 0xb3978 <= bv_unsigned a < 0xb397c -> m a = None) ->   (* [comment removed for export] *)
  mem_inv rsegs m ->
  RHEAP (ps_init (reservedZ rsegs)) [] m
